import os, hashlib, stat, sys
srcroot=b'imported'; dstroot=b'converted'
def sha(p):
 h=hashlib.sha256()
 with open(p,'rb') as f:
  for c in iter(lambda:f.read(65536),b''): h.update(c)
 return h.hexdigest()
ok=True; sources=0; copied=0; collisions=0
for dp,dns,fns in os.walk(srcroot):
 rel=os.path.relpath(dp,srcroot); parts=[] if rel==b'.' else rel.split(b'/')
 outdir=os.path.join(dstroot,*[x.decode('latin-1').encode('utf-8') for x in parts])
 for n in sorted(fns):
  sources+=1; sp=os.path.join(dp,n); tp=os.path.join(outdir,n.decode('latin-1').encode('utf-8'))
  sh=sha(sp)
  try: tp.decode('utf-8'); valid='yes'
  except UnicodeDecodeError: valid='no'; ok=False
  if os.path.exists(tp) and sha(tp)==sh:
   copied+=1; status='COPIED_MATCH'
  elif os.path.exists(tp):
   collisions+=1; status='COLLISION_PRESERVED'
  else:
   ok=False; status='MISSING'
  print(status,'source_hex='+sp.hex(),'destination='+tp.decode('utf-8'),'source_sha256='+sh,'destination_sha256='+(sha(tp) if os.path.exists(tp) else '-'),'destination_utf8='+valid)
print('summary sources=%d copied_matches=%d collisions=%d all_accounted=%s' % (sources,copied,collisions,'yes' if ok and copied+collisions==sources else 'no'))
print('source_tree_entries:')
for dp,dns,fns in os.walk(srcroot):
 for n in sorted(dns+fns): print(os.path.join(dp,n).hex())
print('destination_tree_entries:')
for dp,dns,fns in os.walk(dstroot):
 for n in sorted(dns+fns):
  p=os.path.join(dp,n); print(p.decode('utf-8'),p.hex())
print('report:')
print(open(b'migration-collision-report.txt','rb').read().decode('utf-8'),end='')
if not (ok and copied+collisions==sources): sys.exit(1)
